(() => {
  const el=id=>document.getElementById(id), stage=el('screenStage'), viewport=el('screenViewport'), video=el('screenVideo');
  const bar=document.createElement('div');bar.id='lessonTools';bar.hidden=true;
  bar.innerHTML='<button type="button" id="lessonImport">Abrir apresentação</button><input id="lessonFile" type="file" accept=".pptx,.pdf,.png,.jpg,.jpeg,.webp" multiple hidden><div id="lessonSlides" hidden><button type="button" id="lessonPrevious" aria-label="Slide anterior">←</button><output id="lessonPage">1 / 1</output><button type="button" id="lessonNext" aria-label="Próximo slide">→</button></div><label class="presenter-toggle"><input id="lessonCamera" type="checkbox" checked>Câmera na apresentação</label><span id="lessonStatus" role="status"></span>';
  const openButton=document.createElement('button');openButton.id='openLessonDeck';openButton.type='button';openButton.textContent='Apresentação';openButton.hidden=true;
  document.querySelector('.room-actions').prepend(openButton);stage.querySelector('.screenhead').after(bar);
  const content=document.createElement('div');content.id='lessonContent';viewport.append(content);
  const camera=document.createElement('div');camera.id='presenterOverlay';camera.hidden=true;
  const foreground=document.createElement('canvas');foreground.id='presenterCanvas';foreground.setAttribute('aria-label','Câmera da professora na apresentação');
  const badge=document.createElement('span');badge.className='presenter-caption';camera.append(foreground,badge);content.append(camera);
  const sourceCanvas=document.createElement('canvas');sourceCanvas.id='lessonSource';sourceCanvas.hidden=true;document.body.append(sourceCanvas);
  let hooks, current, controller, cutout, cameraTrack, cameraMirror, session='', page='', enabled=true, localSource=null, deckActive=false, loading=false, disposed=false, view={scale:1,x:0,y:0};
  let remoteSession='',remotePage='',remoteEnabled=true;
  const status=message=>{el('lessonStatus').textContent=message||'';};
  function send(packet,target){return hooks?.send({v:1,...packet},target);}
  function announce(target){if(!session)return;send({type:'state',session,page,enabled,active:!!current?.teacherPresenting},target);}
  function resetCamera(){cutout?.stop();cutout=null;cameraTrack=null;camera.hidden=true;camera.classList.remove('fallback');}
  function layout(){const w=viewport.clientWidth,h=viewport.clientHeight,sw=video.videoWidth,sh=video.videoHeight;if(!sw||!sh||!w||!h)return;const fit=Math.min(w/sw,h/sh);content.style.width=sw*fit+'px';content.style.height=sh*fit+'px';content.style.left=(w-sw*fit)/2+'px';content.style.top=(h-sh*fit)/2+'px';content.style.transform=`translate(${view.x}px,${view.y}px) scale(${view.scale})`;}
  const notes=window.lessonAnnotations.attach({container:content,canEdit:()=>!!(current?.you.role==='teacher'&&current.teacherPresenting&&!current.ended),send:packet=>{if(current?.you.role==='teacher'&&current.teacherPresenting)return send({type:'annotation',session,page,data:packet});},onStatus:status});
  bar.after(notes.toolbar);
  function setPage(next){if(page===next)return;page=next;notes.setPage(page);}
  function syncCamera(){const stream=current?.camera,track=stream?.getVideoTracks()[0],show=current?.teacherPresenting&&(current.you.role==='teacher'?enabled:remoteEnabled)&&track?.readyState==='live';if(!show){resetCamera();return;}const mirror=current.you.role==='teacher';camera.hidden=false;if(cameraTrack===track&&cameraMirror===mirror)return;resetCamera();camera.hidden=false;cameraTrack=track;cameraMirror=mirror;badge.textContent=current.teacher?.name||'Professora';cutout=window.presenterCamera.attach(stream,foreground,{mirror,onStatus:result=>{camera.classList.toggle('fallback',result.state==='fallback');badge.textContent=(current?.teacher?.name||'Professora')+(result.state==='loading'?' · Preparando recorte…':result.state==='fallback'?' · Sem recorte neste navegador':'');},onError:()=>{badge.textContent=(current?.teacher?.name||'Professora')+' · Câmera sem recorte';}});}
  function sync(value){if(disposed)return;current=value;const teacher=value.you?.role==='teacher',canTeach=teacher&&value.you.status==='accepted'&&!value.ended;openButton.hidden=!canTeach;openButton.disabled=loading;bar.hidden=!canTeach||stage.hidden;el('lessonSlides').hidden=!deckActive;el('lessonCamera').checked=enabled;
    const source=value.localScreen?.getVideoTracks()[0];if(teacher&&value.teacherPresenting&&source&&source!==localSource){localSource=source;session=crypto.randomUUID();setPage(session+':'+(deckActive?'slide-'+(controller?.index||0):'screen'));notes.setPage(page);announce();}else if(teacher&&!value.teacherPresenting&&localSource){announce();localSource=null;session='';page='';notes.setPage('inactive');}
    if(!teacher&&remotePage&&page!==remotePage)setPage(remotePage);
    notes.toolbar.hidden=!(canTeach&&value.teacherPresenting);notes.surface.style.display=value.teacherPresenting?'':'none';syncCamera();layout();
  }
  async function loadFiles(files){if(loading||!files?.length||current?.you.role!=='teacher')return;loading=true;openButton.disabled=true;el('lessonImport').disabled=true;status('Abrindo apresentação no dispositivo…');try{controller??=window.lessonDeck.create({canvas:sourceCanvas,onStatus:message=>status(typeof message==='string'?message:message?.message),onPage:info=>{el('lessonPage').textContent=(info.index+1)+' / '+info.count;el('lessonPrevious').disabled=info.index===0;el('lessonNext').disabled=info.index>=info.count-1;if(deckActive&&session){setPage(session+':slide-'+info.index);snapshot();}if(info.warning)status(info.warning);}});if(!await controller.load(files.length===1?files[0]:files))return;deckActive=true;await hooks.startDeck(sourceCanvas);el('lessonSlides').hidden=false;status('Use as setas para trocar os slides. Animações e vídeos do PPTX podem não ser reproduzidos.');}catch(error){deckActive=false;controller?.close();status(error.message||'Não foi possível abrir. Tente exportar o PowerPoint como PDF.');}finally{loading=false;openButton.disabled=false;el('lessonImport').disabled=false;el('lessonFile').value='';}}
  openButton.onclick=()=>el('lessonFile').click();el('lessonImport').onclick=openButton.onclick;
  el('lessonFile').onchange=()=>loadFiles([...el('lessonFile').files]);
  const turn=async method=>{if(loading||!deckActive)return;loading=true;try{await controller[method]();}catch(error){status(error.message);}finally{loading=false;}};
  el('lessonPrevious').onclick=()=>turn('previous');el('lessonNext').onclick=()=>turn('next');
  el('lessonCamera').onchange=()=>{enabled=el('lessonCamera').checked;announce();syncCamera();};
  function snapshot(target){if(current?.you.role!=='teacher'||!current.teacherPresenting)return;announce(target);for(const data of notes.snapshot())send({type:'annotation',session,page,data},target);}
  function receive(member,packet){if(disposed||!packet||packet.v!==1)return;if(packet.type==='request'){if(member.role==='student')snapshot(member.id);return;}if(member.role!=='teacher'||member.id!==current?.teacher?.id||current?.you.role==='teacher')return;if(packet.type==='state'){if(typeof packet.session!=='string'||packet.session.length>64||typeof packet.page!=='string'||packet.page.length>100||typeof packet.enabled!=='boolean'||typeof packet.active!=='boolean')return;remoteSession=packet.active?packet.session:'';remotePage=packet.active?packet.page:'';remoteEnabled=packet.enabled;if(remotePage)setPage(remotePage);else notes.setPage('inactive');syncCamera();}else if(packet.type==='annotation'&&remoteSession&&packet.session===remoteSession&&packet.page===remotePage)notes.receive(packet.data);}
  function peerReady(member){if(current?.you.role==='teacher')snapshot(member.id);else if(member.role==='teacher')send({type:'request'},member.id);}
  function stopDeck(){if(!deckActive)return;deckActive=false;controller?.close();el('lessonSlides').hidden=true;}
  function destroy(){disposed=true;resetCamera();notes.destroy();controller?.close();openButton.disabled=true;bar.hidden=true;}
  video.addEventListener('loadedmetadata',layout);video.addEventListener('resize',layout);new ResizeObserver(layout).observe(viewport);viewport.addEventListener('screenviewchange',event=>{view=event.detail;layout();});
  window.lessonPresenter={configure(value){hooks=value;},sync,receive,peerReady,stopDeck,destroy};
})();
